  "recipes": {
   "gsap": "const split = SplitText.create('.title', { type: 'chars' });\nconst box = el.getBoundingClientRect(), cx = box.left + box.width / 2;\ngsap.to(split.chars, { x: (i, c) => { const r = c.getBoundingClientRect(); return cx - (r.left + r.width / 2); },\n  scale: 0, opacity: 0, duration: 0.5, ease: 'power3.in', stagger: { each: 0.03, from: 'edges' } });",
   "motion": "import { animate } from 'motion';\nconst chars = [...el.querySelectorAll('.c')], n = chars.length, box = el.getBoundingClientRect(), cx = box.left + box.width / 2;\n// 文字ごとに移動量が違うので 1 文字ずつ。端に近い文字ほど早く始める\nchars.forEach((c, i) => { const r = c.getBoundingClientRect();\n  animate(c, { x: cx - (r.left + r.width / 2), scale: 0, opacity: 0 },\n    { duration: 0.5, ease: [0.55, 0.055, 0.675, 0.19], delay: Math.min(i, n - 1 - i) * 0.03 }); });",
   "css": "/* --dx は JS で（中央までの距離）、--d は端からの近さ */\n.c { display:inline-block; animation: collapse .5s cubic-bezier(.55,.055,.675,.19) forwards; animation-delay: calc(var(--d) * 30ms); }\n@keyframes collapse { to { transform: translateX(var(--dx)) scale(0); opacity:0; } }\n@media (prefers-reduced-motion: reduce) { .c { animation-name: fade; } @keyframes fade { to { opacity:0; } } }"
  },
