  "recipeEn": "strike line 0.3s / old word opacity → 0.4 / new word delay 0.2s / scale 0.6 → 1 back.out(2)",
  "curve": "standard",
  "trigger": "時間・状態変化",
  "triggerEn": "Time or state change",
