   "css": ".ph { position:relative; display:inline-block; padding:0 .3em; }\n.ph::before { content:''; position:absolute; left:0; top:0; border:1.5px solid var(--accent);\n  width:0; height:0; transition: width 1s ease-in-out, height 1s ease-in-out; }\n.ph .ptr { position:absolute; left:0; top:0; transition: translate 1s ease-in-out; }\n.ph.is-in::before { width:100%; height:100%; }\n.ph.is-in .ptr { translate: var(--w) var(--h); }   /* JS で実寸を --w/--h に入れる */\n@media (prefers-reduced-motion: reduce) { .ph::before, .ph .ptr { transition:none; } }"
