  "recipe": "yPercent 0 → -100 / 100 → 0 / 0.5s power3.inOut / 1 文字 20ms 差 / overflow: hidden",
  "recipeEn": "yPercent 0 → -100 / 100 → 0 / 0.5s power3.inOut / 20ms per letter / overflow: hidden",
