   "css": ".cube { display:inline-grid; perspective: 600px; height:1.2em; }\n.cube .box { grid-area:1/1; transform-style: preserve-3d; transition: transform .6s cubic-bezier(.65,0,.35,1);\n  transform: translateZ(-.6em); }\n.cube .face { grid-area:1/1; backface-visibility:hidden; }\n.cube .front  { transform: translateZ(.6em); }\n.cube .bottom { transform: rotateX(-90deg) translateZ(.6em); }\n.cube.next .box { transform: translateZ(-.6em) rotateX(90deg); }\n@media (prefers-reduced-motion: reduce) { .cube .box { transition:none; } }",
