   "css": ".jump span { display: inline-block; transform-origin: 50% 100%;\n  animation: jump 1.1s both; animation-delay: calc(var(--i) * 60ms); }\n@keyframes jump {\n  0%   { transform: none; }\n  7%   { transform: scale(1.08, .9); animation-timing-function: cubic-bezier(.5, 1, .89, 1); }\n  31%  { transform: translateY(-60%) scale(1, 1); animation-timing-function: cubic-bezier(.11, 0, .5, 0); }\n  49%  { transform: translateY(0) scale(.85, 1.2); }\n  56%  { transform: scale(1.25, .7); }\n  70%  { transform: scale(.94, 1.08); } 84% { transform: scale(1.02, .98); } 100% { transform: none; } }\n@media (prefers-reduced-motion: reduce) { .jump span { animation: none; } }",
   "gsap": "const split = SplitText.create('.jump', { type: 'chars', aria: 'auto' });\ngsap.set(split.chars, { transformOrigin: '50% 100%' });\nsplit.chars.forEach((c, i) => gsap.timeline({ delay: i * 0.06 })\n  .to(c, { yPercent: -60, scaleY: 1.2, scaleX: 0.85, duration: 0.26, ease: 'power2.out' })\n  .to(c, { scaleY: 1, scaleX: 1, duration: 0.1 }, '<0.16')\n  .to(c, { yPercent: 0, scaleY: 1.2, scaleX: 0.85, duration: 0.2, ease: 'power2.in' })\n  .to(c, { scaleY: 0.7, scaleX: 1.25, duration: 0.08, ease: 'power2.out' })\n  .to(c, { scaleY: 1, scaleX: 1, duration: 0.5, ease: 'elastic.out(1, 0.4)' }));",
