  "valuesEn": [
   "sample step 4–6px (demo ≈3px)",
   "repel radius 80px (demo 38px)",
   "spring 0.05–0.1",
   "damping 0.9"
  ],
  "recipes": {
   "canvas": "// 1) 文字を描いてピクセルを拾う\nconst off = new OffscreenCanvas(w, h), o = off.getContext('2d');\no.font = '900 160px sans-serif'; o.textAlign = 'center'; o.textBaseline = 'middle'; o.fillText(text, w / 2, h / 2);\nconst data = o.getImageData(0, 0, w, h).data, P = [];\nfor (let y = 0; y < h; y += 5) for (let x = 0; x < w; x += 5)\n  if (data[(y * w + x) * 4 + 3] > 128) P.push({ hx: x, hy: y, x, y, vx: 0, vy: 0 });\n// 2) 毎フレーム：カーソルから離れる力＋元の位置へのバネ＋減衰\nfunction tick() {\n  ctx.clearRect(0, 0, w, h);\n  for (const p of P) {\n    const dx = p.x - mouse.x, dy = p.y - mouse.y, d = Math.hypot(dx, dy);\n    if (d < 80) { const f = (1 - d / 80) * 6; p.vx += dx / d * f; p.vy += dy / d * f; }\n    p.vx = (p.vx + (p.hx - p.x) * 0.08) * 0.9; p.vy = (p.vy + (p.hy - p.y) * 0.08) * 0.9;\n    p.x += p.vx; p.y += p.vy; ctx.fillRect(p.x, p.y, 2, 2);\n  }\n  requestAnimationFrame(tick);\n}",
   "css": "/* 点の文字は装飾。本物の見出しは視覚的に隠して残す */\n.particles { position: relative; } .particles canvas { display: block; width: 100%; }\n.particles h1 { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }\n@media (prefers-reduced-motion: reduce) { .particles canvas { display: none; } .particles h1 { position: static; width: auto; height: auto; clip-path: none; } }"
  },
