  "reduced": "動きを止め、文字が読める代表のコマを表示します。",
  "reducedEn": "Stop the motion and show a representative frame where the text is readable.",
  "accent": "yellow",
  "featured": false,
  "values": [
   "curveAmount 400",
   "speed 2px / frame",
   "startOffset ループ",
   "区切り「•」で継ぎ目を隠す"
  ],
  "valuesEn": [
   "curveAmount 400",
   "speed 2px / frame",
   "startOffset loop",
   "separator “•” hides the seam"
  ],
  "recipes": {
   "svg": "<svg viewBox=\"0 0 1440 160\" role=\"img\" aria-label=\"Flowing words\">\n  <path id=\"curve\" d=\"M-100,60 Q620,160 1540,60\" fill=\"none\"/>\n  <text font-size=\"48\" aria-hidden=\"true\">\n    <textPath id=\"tp\" href=\"#curve\">Flowing words • Flowing words • Flowing words •</textPath>\n  </text>\n</svg>\n<script>\n  // rAF ごとに startOffset を 2px 減らし、1 単位の長さで巻き戻す\n  const tp = document.getElementById('tp'), unit = tp.getComputedTextLength() / 3;\n  let offset = 0;\n  const tick = () => { offset -= 2; if (offset <= -unit) offset += unit; tp.setAttribute('startOffset', offset); requestAnimationFrame(tick); };\n  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) requestAnimationFrame(tick);\n</script>",
   "canvas": "// Canvas 版：弧長テーブルを作り、文字ごとに位置と接線角を求める\nfunction drawMarquee(ctx, text, offset) {          // text は「文 • 」を何回か繰り返したもの\n  const N = 400, pts = [], acc = [0];\n  for (let k = 0; k <= N; k++) { const u = k / N; pts.push([u * 1440, 60 + 100 * Math.sin(u * Math.PI)]); }\n  for (let k = 1; k <= N; k++) acc.push(acc[k - 1] + Math.hypot(pts[k][0] - pts[k - 1][0], pts[k][1] - pts[k - 1][1]));\n  const at = d => { let i = acc.findIndex(a => a >= d); if (i < 1) i = 1; const [a, b] = [pts[i - 1], pts[i]]; return [b[0], b[1], Math.atan2(b[1] - a[1], b[0] - a[0])]; };\n  let d = offset;\n  for (const ch of text) {\n    const w = ctx.measureText(ch).width, c = d + w / 2; d += w;\n    if (c < 0 || c > acc[N]) continue;\n    const [x, y, ang] = at(c); ctx.save(); ctx.translate(x, y); ctx.rotate(ang); ctx.fillText(ch, -w / 2, 0); ctx.restore();\n  }\n}"
  },
