   "css": "/* <h1 class=\"split\" data-text=\"Lock Together\">Lock Together</h1> */\n.split { position: relative; color: transparent; }\n.split::before, .split::after { content: attr(data-text); position: absolute; inset: 0; color: var(--ink);\n  animation: .7s cubic-bezier(.16,1,.3,1) both; }\n.split::before { clip-path: inset(0 0 50% 0); animation-name: fromL; }\n.split::after  { clip-path: inset(50% 0 0 0); animation-name: fromR; }\n@keyframes fromL { from { translate: -200px 0; } }\n@keyframes fromR { from { translate: 200px 0; } }\n@media (prefers-reduced-motion: reduce) { .split::before, .split::after { animation: none; } }",
