   "css": ".bar { position: relative; }\n.bar::after { content: ''; position: absolute; inset: 0; background: var(--accent);\n  transform: scaleX(0); transform-origin: left; animation: bar .8s ease-in-out forwards; }\n.bar > span { clip-path: inset(0 100% 0 0); animation: show .4s ease-in-out .4s forwards; }\n@keyframes bar { 50% { transform: scaleX(1); transform-origin: left; } 50.01% { transform-origin: right; } 100% { transform: scaleX(0); transform-origin: right; } }\n@keyframes show { to { clip-path: inset(0 0 0 0); } }\n@media (prefers-reduced-motion: reduce) { .bar::after { display: none; } .bar > span { animation: none; clip-path: none; } }",
