   "waapi": "// @property で登録済みなら、WAAPI でも角度が補間される\nCSS.registerProperty?.({ name: '--angle', syntax: '<angle>', inherits: false, initialValue: '0deg' });\ndocument.querySelector('.spin').animate({ '--angle': ['0deg', '360deg'] }, { duration: 4000, iterations: Infinity, easing: 'linear' });",
