  "recipes": {
   "css": ".lines { position: relative; z-index: 0; }\n.lines::after { content: attr(data-text); position: absolute; left: .04em; top: .04em; z-index: -1;\n  background: linear-gradient(45deg, transparent 45%, #7d64ff 45%, #7d64ff 55%, transparent 0) 0 0 / .06em .06em;\n  -webkit-background-clip: text; background-clip: text; color: transparent;\n  animation: line-shadow 15s linear infinite; }\n@keyframes line-shadow { to { background-position: 100% -100%; } }\n@media (prefers-reduced-motion: reduce) { .lines::after { animation: none; } }\n/* <h1 class=\"lines\" data-text=\"Stripes\">Stripes</h1> */",
   "canvas": "// 影の文字でマスクして、斜線を流す\nlg.fillText(text, x + off, y + off);\nlg.globalCompositeOperation = 'source-in';\nlg.beginPath(); for (let x0 = -h; x0 < w + h; x0 += gap) { lg.moveTo(x0 + phase, 0); lg.lineTo(x0 + phase - h, h); }\nlg.lineWidth = gap * .45; lg.stroke();\nctx.drawImage(layer, 0, 0); ctx.fillText(text, x, y);   // 本体を上に"
  },
