  "recipes": {
   "motion": "import { animate } from 'motion';\nconst words = [...document.querySelectorAll('.tf .w')], frame = document.querySelector('.tf .frame');\nlet i = 0;\nfunction focusOn(n) {\n  words.forEach((w, k) => w.style.filter = k === n ? 'blur(0)' : 'blur(5px)');   // CSS 側で transition: filter .5s\n  const r = words[n].getBoundingClientRect(), p = frame.parentElement.getBoundingClientRect();\n  animate(frame, { x: r.left - p.left, y: r.top - p.top, width: r.width, height: r.height }, { duration: .5 });\n}\nsetInterval(() => focusOn(i = (i + 1) % words.length), 1500);",
   "css": ".tf { position: relative; }\n.tf .w { filter: blur(5px); transition: filter .5s ease; }\n.tf .w.on { filter: none; }\n.tf .frame { position: absolute; left: 0; top: 0; pointer-events: none;   /* aria-hidden=\"true\" */\n  background:\n    linear-gradient(#7d64ff 0 0) 0 0 / 10px 2px no-repeat, linear-gradient(#7d64ff 0 0) 0 0 / 2px 10px no-repeat,\n    linear-gradient(#7d64ff 0 0) 100% 0 / 10px 2px no-repeat, linear-gradient(#7d64ff 0 0) 100% 0 / 2px 10px no-repeat,\n    linear-gradient(#7d64ff 0 0) 0 100% / 10px 2px no-repeat, linear-gradient(#7d64ff 0 0) 0 100% / 2px 10px no-repeat,\n    linear-gradient(#7d64ff 0 0) 100% 100% / 10px 2px no-repeat, linear-gradient(#7d64ff 0 0) 100% 100% / 2px 10px no-repeat;\n  transition: transform .5s ease, width .5s ease, height .5s ease; }\n@media (prefers-reduced-motion: reduce) { .tf .w { filter: none; } .tf .frame { transition: none; } }"
  },
