   "css": "<a class=\"roll\" aria-label=\"Flip Over\">\n  <span class=\"c\" style=\"--i:0\" aria-hidden=\"true\"><b>F</b><i>F</i></span>…\n</a>\n.roll .c { display: inline-block; position: relative; transform-style: preserve-3d;\n  transition: transform .4s ease-in-out; transition-delay: calc(var(--i) * 30ms); }\n.roll .c b { display: block; transform: translateZ(.5em); }\n.roll .c i { position: absolute; inset: 0; font-style: normal; font-family: serif; color: var(--accent);\n  transform: rotateX(-90deg) translateZ(.5em); }\n.roll:hover .c { transform: rotateX(90deg); }\n@media (prefers-reduced-motion: reduce) { .roll .c { transition: none; } }",
