   "css": "<h1 class=\"depth\"><span>DEPTH</span>\n  <span aria-hidden=\"true\" style=\"--i:1\">DEPTH</span> … <span aria-hidden=\"true\" style=\"--i:12\">DEPTH</span></h1>\n.depth { display: grid; transform-style: preserve-3d;\n  transform: rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg)); }\n.depth span { grid-area: 1/1; transform: translateZ(calc(var(--i, 0) * -1px)); }\n.depth span[aria-hidden] { color: color-mix(in oklab, var(--accent), black calc(var(--i) * 6%)); }",
   "motion": "import { animate, springValue } from 'motion';   // Motion 12\nconst el = document.querySelector('.depth');\nconst rx = springValue(0, { stiffness: 120, damping: 16 });\nconst ry = springValue(0, { stiffness: 120, damping: 16 });\nconst apply = () => el.style.transform = `rotateX(${rx.get()}deg) rotateY(${ry.get()}deg)`;\nrx.on('change', apply); ry.on('change', apply);\naddEventListener('pointermove', e => {\n  ry.set((e.clientX / innerWidth - .5) * 30);    // ±15°\n  rx.set(-(e.clientY / innerHeight - .5) * 30);\n});"
