   "gsap": "gsap.fromTo('.breathe', { fontVariationSettings: \"'wght' 100\" },\n  { fontVariationSettings: \"'wght' 900\", duration: 3, ease: 'sine.inOut', repeat: -1, yoyo: true });",
   "remotion": "const frame = useCurrentFrame(); const { fps } = useVideoConfig();\nconst p = (1 - Math.cos((frame / fps) * Math.PI / 3)) / 2;   // 3 秒で 0→1、6 秒で戻る\nreturn <h1 style={{ fontVariationSettings: `'wght' ${interpolate(p, [0, 1], [100, 900])}` }}>{text}</h1>;",
