   "gsap": "const split = SplitText.create('.lean', { type: 'chars', aria: 'auto' });\ngsap.to(split.chars, { '--slnt': -10, duration: 1, ease: 'sine.inOut',\n  stagger: { each: .08, repeat: -1, yoyo: true } });",
