  "recipes": {
   "motion": "function Word({ children, range, progress }) {\n  const opacity = useTransform(progress, range, [0.15, 1]);\n  return <motion.span style={{ opacity }}>{children} </motion.span>;\n}\nfunction Paragraph({ words }) {\n  const ref = useRef(null);\n  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] });\n  return <section ref={ref} style={{ height: '220vh' }}><p style={{ position: 'sticky', top: '30vh' }}>\n    {words.map((w, i) => { const s = i / (words.length - 1) * .8; return <Word key={i} progress={scrollYProgress} range={[s, s + .2]}>{w}</Word>; })}\n  </p></section>;\n}",
   "gsap": "const split = SplitText.create('.reveal', { type: 'words' });\ngsap.fromTo(split.words, { opacity: .15 }, { opacity: 1, ease: 'none', stagger: .05,\n  scrollTrigger: { trigger: '.reveal', start: 'top 70%', end: 'bottom 30%', scrub: true } });",
   "css": "/* 対応ブラウザだけ：行ごとに view() で明るく */\n@supports (animation-timeline: view()) {\n  .reveal .w { animation: lit linear both; animation-timeline: view(); animation-range: entry 0% cover 40%; }\n  @keyframes lit { from { opacity: .15; } to { opacity: 1; } }\n}"
  },
