   "gsap": "const cols = [...document.querySelectorAll('.wave-col')];   // 2 列\nScrollTrigger.create({ trigger: '.wave-section', start: 'top bottom', end: 'bottom top',\n  onUpdate() {\n    cols.forEach((col, c) => col.querySelectorAll('li').forEach(li => {\n      const r = li.getBoundingClientRect(), y = r.top + r.height / 2 - innerHeight / 2;\n      const sign = c ? -1 : 1;\n      gsap.set(li, { x: sign * innerWidth * .12 * Math.sin(y * .006 + 1.1) });\n      li.classList.toggle('is-center', Math.abs(y) < r.height / 2);\n    }));\n  } });",
   "css": ".wave-col li { transition: color .2s, font-size .2s; }\n.wave-col li.is-center { color: var(--accent); font-size: 1.3em; font-weight: 800; }\n@media (prefers-reduced-motion: reduce) { .wave-col li { transform: none !important; } }"
