   "gsap": "// <h2 class=\"echo\"><span class=\"main\">ECHO</span></h2> に複製を足す\nconst h = document.querySelector('.echo'), N = 6;\nconst copies = Array.from({ length: N }, (_, i) => {\n  const c = h.querySelector('.main').cloneNode(true); c.className = 'copy'; c.setAttribute('aria-hidden', 'true');\n  h.prepend(c); return c;\n});\ngsap.timeline({ scrollTrigger: { trigger: h, start: 'top 80%', end: 'bottom 20%', scrub: true } })\n  .fromTo(copies, { rotate: 0, opacity: 0 }, {\n    rotate: i => (i % 2 ? 1 : -1) * 7 * Math.ceil((i + 1) / 2),\n    opacity: i => 1 - Math.ceil((i + 1) / 2) / 4, transformOrigin: '50% 400%', ease: 'power2.inOut' })\n  .to(copies, { rotate: 0, opacity: 0, ease: 'power2.inOut' });",
   "css": ".echo { display: grid; }\n.echo > * { grid-area: 1 / 1; }\n.echo .copy { color: transparent; -webkit-text-stroke: 1px currentColor; transform-origin: 50% 400%; }\n.echo .main { position: relative; }   /* 本体は最前面 */"
