   "gsap": "gsap.utils.toArray('.para-line').forEach(line => {\n  const speed = parseFloat(line.dataset.speed);          // data-speed=\"1.4\" など\n  gsap.fromTo(line, { y: 120 * speed }, { y: -120 * speed, ease: 'none',\n    scrollTrigger: { trigger: '.para-section', start: 'top bottom', end: 'bottom top', scrub: true } });\n});",
   "css": ".para-section { overflow: clip; }\n@supports (animation-timeline: view()) {\n  .para-line { animation: drift linear both; animation-timeline: view(); }\n  @keyframes drift { from { translate: 0 calc(120px * var(--speed)); } to { translate: 0 calc(-120px * var(--speed)); } }\n}\n@media (prefers-reduced-motion: reduce) { .para-line { animation: none; } }",
