  "recipes": {
   "gsap": "const split = SplitText.create('.magnet', { type: 'chars' }); // aria は自動で付く\nconst R = 120, S = 0.4;\nconst movers = split.chars.map(el => ({ el,\n  x: gsap.quickTo(el, 'x', { duration: .4, ease: 'power3' }),\n  y: gsap.quickTo(el, 'y', { duration: .4, ease: 'power3' }) }));\nwindow.addEventListener('pointermove', e => {\n  for (const m of movers) {\n    const b = m.el.getBoundingClientRect();\n    const dx = e.clientX - (b.left + b.width / 2) + gsap.getProperty(m.el, 'x');\n    const dy = e.clientY - (b.top + b.height / 2) + gsap.getProperty(m.el, 'y');\n    const d = Math.hypot(dx, dy), k = d < R ? (1 - d / R) * S : 0;\n    m.x(dx * k); m.y(dy * k);\n  }\n});",
   "motion": "import { animate } from 'motion';\n// chars は aria-hidden の <span>。親に aria-label で全文を持たせる\ndocument.addEventListener('pointermove', e => {\n  chars.forEach(el => {\n    const r = el.getBoundingClientRect();\n    const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);\n    const d = Math.hypot(dx, dy), k = d < 120 ? (1 - d / 120) * 0.4 : 0;\n    animate(el, { x: dx * k, y: dy * k }, { type: 'spring', stiffness: 300, damping: 24 });\n  });\n});\nif (matchMedia('(prefers-reduced-motion: reduce)').matches) { /* リスナーを付けない */ }"
  },
