   "svg": "<svg viewBox=\"0 0 300 100\" role=\"img\" aria-label=\"照らす\">\n  <defs>\n    <linearGradient id=\"hue\"><stop offset=\"0\" stop-color=\"#f2c84b\"/><stop offset=\".5\" stop-color=\"#7d64ff\"/><stop offset=\"1\" stop-color=\"#22bdd6\"/></linearGradient>\n    <radialGradient id=\"spot\" gradientUnits=\"userSpaceOnUse\" r=\"60\" cx=\"50%\" cy=\"50%\">\n      <stop offset=\"0\" stop-color=\"#fff\"/><stop offset=\"1\" stop-color=\"#000\"/></radialGradient>\n    <mask id=\"m\"><rect width=\"100%\" height=\"100%\" fill=\"url(#spot)\"/></mask>\n  </defs>\n  <text class=\"draw\" x=\"50%\" y=\"70\" text-anchor=\"middle\" fill=\"none\" stroke=\"#6c778b\">照らす</text>\n  <text x=\"50%\" y=\"70\" text-anchor=\"middle\" fill=\"none\" stroke=\"url(#hue)\" stroke-width=\"2\" mask=\"url(#m)\">照らす</text>\n</svg>\n<style>.draw { stroke-dasharray: 1000; stroke-dashoffset: 1000; animation: draw 4s ease-in-out forwards; }\n@keyframes draw { to { stroke-dashoffset: 0; } }\n@media (prefers-reduced-motion: reduce) { .draw { animation: none; stroke-dashoffset: 0; } }</style>\n<script>svg.addEventListener('pointermove', e => { const r = svg.getBoundingClientRect(), g = svg.querySelector('#spot');\n  g.setAttribute('cx', (e.clientX - r.left) / r.width * 300); g.setAttribute('cy', (e.clientY - r.top) / r.height * 100); });</script>",
