  "valuesEn": [
   "spin 750ms",
   "opacity 350ms ease-out",
   "mask 0.25em",
   "line-height 0.85–1"
  ],
  "recipes": {
   "css": "/* 桁ごとに 0〜9 を縦に並べた帯を overflow:hidden の窓で切り出す */\n.digit { display: inline-block; height: 1em; line-height: 1; overflow: hidden;\n  mask-image: linear-gradient(transparent, #000 .25em, #000 calc(100% - .25em), transparent); }\n.digit .strip { display: flex; flex-direction: column; translate: 0 calc(var(--d) * -1em);\n  transition: translate .75s cubic-bezier(.25,1,.5,1); }\n@media (prefers-reduced-motion: reduce) { .digit .strip { transition: none; } }\n/* JS: el.style.setProperty('--d', 7) */",
   "motion": "// NumberFlow（React）：桁ロールとマスクを内蔵\nimport NumberFlow from '@number-flow/react';\n<NumberFlow value={value} trend={1} spinTiming={{ duration: 750, easing: 'ease-out' }}\n  opacityTiming={{ duration: 350, easing: 'ease-out' }} format={{ useGrouping: true }} />\n// Motion+ なら <AnimateNumber>{value}</AnimateNumber>",
   "gsap": "// 各桁の帯 .strip を目標の数字へ\ndigits.forEach((strip, i) => gsap.to(strip, { yPercent: -10 * next[i], duration: .75, ease: 'power3.out' }));",
   "ae": "1. 桁ごとに「0 1 2 … 9」を縦に並べたテキストレイヤーを作る（行送り = 文字サイズ）\n2. 位置 Y にエクスプレッション：value - Math.floor(slider / 10^桁) % 10 * 行送り\n3. 窓の大きさの長方形マスク＋上下に 25% のぼかし（マスクの境界のぼかし）\n4. スライダーを 1024 → 2048 でキーフレーム",
   "aeEn": "1. Per digit, a text layer with “0 1 2 … 9” stacked vertically (leading = font size)\n2. Position Y expression: value - Math.floor(slider / 10^place) % 10 * leading\n3. Rectangular window mask with ~25% mask feather top/bottom\n4. Keyframe the slider 1024 → 2048"
  },
