   "css": "@property --p { syntax: '<integer>'; initial-value: 0; inherits: true; }\n.ring { --p: 87; animation: fill 1.6s cubic-bezier(.5,1,.89,1) both; }   /* ≈ power2.out */\n.ring .bar { stroke-dashoffset: calc(100 - var(--p)); }\n.ring .pct::before { counter-reset: p var(--p); content: counter(p) \"%\"; }\n@keyframes fill { from { --p: 0; } }\n@media (prefers-reduced-motion: reduce) { .ring { animation: none; } }",
