  "recipes": {
   "css": "/* 7 本の棒を data-on で点灯。数字 → 文字列 \"abcdefg\" の対応は JS */\n.seg { opacity: .08; transition: opacity 60ms linear; fill: var(--accent); }\n.digit[data-on~=\"a\"] .a, .digit[data-on~=\"b\"] .b, .digit[data-on~=\"c\"] .c, .digit[data-on~=\"d\"] .d,\n.digit[data-on~=\"e\"] .e, .digit[data-on~=\"f\"] .f, .digit[data-on~=\"g\"] .g { opacity: 1; }\n.lcd { filter: drop-shadow(0 0 4px var(--accent)); }\n.colon { animation: blink 1s steps(1) infinite; }\n@keyframes blink { 50% { opacity: .08; } }\n@media (prefers-reduced-motion: reduce) { .colon { animation: none; } }",
   "svg": "<!-- 1 桁（viewBox 0 0 40 72）。各 polygon に class a〜g -->\n<g class=\"digit\" data-on=\"a b c d e f\">\n  <polygon class=\"seg a\" points=\"4,2 36,2 32,7 8,7\"/>   <polygon class=\"seg g\" points=\"6,36 10,33 30,33 34,36 30,39 10,39\"/>\n  <polygon class=\"seg d\" points=\"8,65 32,65 36,70 4,70\"/> <polygon class=\"seg f\" points=\"2,4 7,8 7,32 2,35\"/>\n  <polygon class=\"seg b\" points=\"38,4 38,35 33,32 33,8\"/> <polygon class=\"seg e\" points=\"2,37 7,40 7,64 2,68\"/>\n  <polygon class=\"seg c\" points=\"38,37 38,68 33,64 33,40\"/>\n</g>\n<script>const MAP = ['abcdef','bc','abdeg','abcdg','bcfg','acdfg','acdefg','abc','abcdefg','abcdfg'];\ndigitEl.dataset.on = MAP[n].split('').join(' ');</script>",
   "canvas": "const MAP = [0x3f, 0x06, 0x5b, 0x4f, 0x66, 0x6d, 0x7d, 0x07, 0x7f, 0x6f]; // bit0=a … bit6=g\nfunction drawDigit(ctx, n, segs) {          // segs[k] = Path2D of segment k\n  for (let k = 0; k < 7; k++) { ctx.globalAlpha = MAP[n] >> k & 1 ? 1 : .08; ctx.fill(segs[k]); }\n  ctx.globalAlpha = 1;\n}"
  },
