  "recipes": {
   "css": "/* 3 行ぶんの窓。新しい行を末尾に足し、全体を 1 行ぶん持ち上げる */\n.roll { height: calc(3 * 1.45em); overflow: hidden; display: flex; flex-direction: column; justify-content: flex-end; }\n.roll .lines { transition: transform .27s cubic-bezier(.33,1,.68,1); }\n.roll .lines.rolling { transform: translateY(-1.45em); }\n@media (prefers-reduced-motion: reduce) { .roll .lines { transition: none; } }",
   "waapi": "// 行を追加 → 1 行ぶん下から元の位置へ（FLIP）。aria-live で読み上げにも流す\nfunction addLine(box, text) {\n  const p = document.createElement('p'); p.textContent = text; box.append(p);\n  while (box.children.length > 3) box.firstElementChild.remove();\n  box.animate([{ transform: 'translateY(1.45em)' }, { transform: 'none' }], { duration: 270, easing: 'cubic-bezier(.33,1,.68,1)' });\n}\n// <div class=\"roll\" aria-live=\"polite\"></div>"
  },
