  "recipes": {
   "remotion": "import { createTikTokStyleCaptions } from '@remotion/captions';\nconst { pages } = createTikTokStyleCaptions({ captions, combineTokensWithinMilliseconds: 1200 });\n\nconst Page = ({ page }) => {\n  const frame = useCurrentFrame(); const { fps } = useVideoConfig();\n  const t = page.startMs + (frame / fps) * 1000;\n  return <div style={{ whiteSpace: 'pre' }}>{page.tokens.map(tk => {\n    const on = tk.fromMs <= t && t < tk.toMs;\n    return <span key={tk.fromMs} style={{ display: 'inline-block', color: on ? '#7d64ff' : '#fff', transform: `scale(${on ? 1.1 : 1})` }}>{tk.text}</span>;\n  })}</div>;\n};\n// pages.map(p => <Sequence from={p.startMs / 1000 * fps}><Page page={p} /></Sequence>)",
   "css": "/* JS で現在語に .on を付ける。読み上げ用の全文は別に置く */\n.page span { display: inline-block; transition: transform 80ms cubic-bezier(.33,1,.68,1), color 80ms; }\n.page span.on { color: var(--accent); transform: scale(1.1); }\n@media (prefers-reduced-motion: reduce) { .page span.on { transform: none; text-decoration: underline; } }",
   "ae": "1. 語ごとにマーカー（音声に合わせる）\n2. アニメーター：塗りのカラー＋スケール 110%\n3. 範囲セレクター → 単位：インデックス、基準：単語\n4. 開始/終了をマーカーに合わせて 1 語ずつ進める（ホールドキー）",
   "aeEn": "1. Add a marker per word (synced to the audio)\n2. Animator: Fill Color + Scale 110%\n3. Range Selector → Units: Index, Based On: Words\n4. Step Start/End one word at a time on the markers (hold keys)"
  },
