   "waapi": "// FLIP：位置を記録 → 並び替え → 差分を transform で戻して 0 へ\nconst first = new Map([...el.children].map(c => [c, c.getBoundingClientRect()]));\norder.forEach(c => el.append(c)); // 新しい語の順に DOM を並べ替え\n[...el.children].forEach((c, i) => {\n  const f = first.get(c), l = c.getBoundingClientRect();\n  c.animate([{ transform: `translate(${f.left - l.left}px, ${f.top - l.top}px)` }, { transform: 'none' }],\n    { duration: 600, delay: i * 20, easing: 'cubic-bezier(.2,.8,.2,1)' });\n});\nel.setAttribute('aria-label', newWord); // 文字 span は aria-hidden",
