   "motion": "// 文字ごとに安定した key（文字＋出現番号）を付けると layout で移動する\n<p>{letters.map(l => <motion.span key={l.id} layout transition={{ duration: .6, ease: [.2, .8, .2, 1] }}>{l.ch}</motion.span>)}</p>"
