   "waapi": "// 非対応環境：scrollHeight を測って px で補間 → 終わったら auto に戻す\nbtn.onclick = () => {\n  const from = box.offsetHeight; box.classList.add('open');\n  const to = box.scrollHeight;\n  box.animate([{ height: from + 'px' }, { height: to + 'px' }], { duration: 450, easing: 'ease' });\n  btn.setAttribute('aria-expanded', 'true');\n};",
   "motion": "<motion.div initial={false} animate={{ height: open ? 'auto' : '1.5em' }} transition={{ duration: .45, ease: 'easeInOut' }} style={{ overflow: 'hidden' }}>\n  <p style={open ? {} : { display: '-webkit-box', WebkitLineClamp: 1, WebkitBoxOrient: 'vertical' }}>{text}</p>\n</motion.div>\n<button aria-expanded={open} onClick={() => setOpen(!open)}>{open ? '閉じる' : '続きを読む'}</button>"
