   "css": ".sign { position: relative; display:inline-block; transform-origin: 50% -40%;\n  animation: sway 2.4s ease-in-out infinite alternate; }\n.sign::before, .sign::after { content:''; position:absolute; bottom:100%; height:1.2em;\n  border-left: 1px solid currentColor; }\n.sign::before { left: 15%; transform: skewX(20deg); } .sign::after { right: 15%; transform: skewX(-20deg); }\n@keyframes sway { from { transform: rotate(-4deg); } to { transform: rotate(4deg); } }\n@media (prefers-reduced-motion: reduce) { .sign { animation: none; } }",
