   "gsap": "gsap.set('.crawl', { transformPerspective: 400, rotationX: 25, transformOrigin: '50% 100%' });\ngsap.fromTo('.crawl > div', { yPercent: 100 }, { yPercent: -200, duration: 60, ease: 'none' });",
