   "css": ".banner { transform-origin: left; animation: wipe .27s cubic-bezier(.33,1,.68,1) both, flash .75s steps(1) .27s 1; }\n@keyframes wipe { from { transform: scaleX(0); } }\n@keyframes flash { 0%, 33%, 67% { background: #fff; } 17%, 50%, 83% { background: var(--red); } }\n.banner span { animation: slam .2s cubic-bezier(.16,1,.3,1) .47s both; }\n@keyframes slam { from { transform: translateX(140px) skewX(17deg); opacity: 0; } }\n@media (prefers-reduced-motion: reduce) { .banner, .banner span { animation: none; } }",
