   "css": ".credits { animation: roll var(--d) linear forwards; }\n@keyframes roll { from { transform: translateY(100vh); } to { transform: translateY(-100%); } }\n/* --d = (内容の高さ + 画面の高さ) / 120px/s → 60fps で 2px/コマ */\n.credits { color: #ebebeb; background: #101010; }\n@media (prefers-reduced-motion: reduce) { .credits { animation: none; overflow: auto; } }",
   "canvas": "const pxPerFrame = 2;   // 整数\nlet frame = 0;\n(function tick() {\n  frame++;\n  const y = h - frame * pxPerFrame;\n  ctx.clearRect(0, 0, w, h);\n  rows.forEach((r, i) => ctx.fillText(r, w / 2, y + i * 40));\n  if (y + rows.length * 40 > 0) requestAnimationFrame(tick);\n})();",
