   "css": ".telop { background: linear-gradient(105deg, var(--c) 40%, #fff 50%, var(--c) 60%) 200% 0 / 300% 100%;\n  -webkit-background-clip: text; background-clip: text; color: transparent; animation: pop .23s cubic-bezier(.34,1.56,.64,1) both, sweep .6s ease-in-out .75s both; }\n@keyframes pop { from { opacity: 0; transform: scale(.7); } }\n@keyframes sweep { to { background-position: -100% 0; } }\n.spark { animation: burst .8s cubic-bezier(.33,1,.68,1) both; }\n@keyframes burst { 50% { opacity: 1; scale: 1; } to { opacity: 0; scale: 0; translate: var(--dx) var(--dy); } }\n@media (prefers-reduced-motion: reduce) { .telop, .spark { animation: none; } .spark { display: none; } }",
